import re
from html.parser import HTMLParser

BASE = "https://www.legis.iowa.gov"
BLOCK = {"p", "div", "br", "li", "tr", "table", "h1", "h2", "h3", "h4", "h5", "h6", "ul", "ol", "pre", "blockquote"}

def _cls(attrs):
    return (dict(attrs).get("class") or "").split()

class Chapter(HTMLParser):
    """Each <div class="x-codeSection-N-M"> of an Arbortext chapter page: first identifier = id, first headnote = heading,
    the rest = text. Dropped: header/meta/footer, 'Referred to in' references, the heading block itself."""
    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.out, self.cur, self.stack = [], None, []
    def handle_starttag(self, tag, attrs):
        c = _cls(attrs)
        if self.cur is None:
            if tag == "div" and any(re.match(r"x-codeSection-\d", t) for t in c):
                self.cur = {"id": [], "heading": [], "text": [], "idn": 0, "hn": 0}
                self.stack = [("div", "sec")]
            return
        role = None
        if any(t.startswith(("x-references", "x-header", "x-footer", "x-meta")) for t in c) or tag in ("script", "style"):
            role = "skip"
        elif any(t.startswith("x-identifier-") for t in c) and not self.cur["idn"]:
            role = "id"; self.cur["idn"] = 1
        elif any(t.startswith("x-headnote-") for t in c) and not self.cur["hn"]:
            role = "head"; self.cur["hn"] = 1
        elif any(t.startswith("x-codeSectionVersionAnnotation") or t.startswith("x--ufe-codeSectionVersionAnnotation") for t in c):
            role = "skip"
        self.stack.append((tag, role))
        if tag in BLOCK and tag != "br":
            self.cur["text"].append("\n")
        if tag == "br":
            self.stack.pop(); self.cur["text"].append("\n")
    def handle_startendtag(self, tag, attrs):
        if self.cur is not None and tag == "br":
            self.cur["text"].append("\n")
    def handle_endtag(self, tag):
        if self.cur is None:
            return
        # pop to the matching tag (tolerates unclosed inner tags)
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0] == tag:
                del self.stack[i:]
                break
        else:
            return
        if tag in BLOCK:
            self.cur["text"].append("\n")
        if not self.stack:
            self.out.append(self.cur); self.cur = None
    def handle_data(self, d):
        if self.cur is None:
            return
        d = re.sub(r"\s+", " ", d)
        roles = [r for _, r in self.stack]
        if "skip" in roles:
            return
        if "id" in roles:
            self.cur["id"].append(d)
        elif "head" in roles:
            self.cur["heading"].append(d)
        else:
            self.cur["text"].append(d)

def _lines(s):
    return "\n".join(l for l in (" ".join(x.split()) for x in s.split("\n")) if l)

def chapter_sections(html):
    p = Chapter(); p.feed(html); p.close()
    for s in p.out:
        sid = "".join("".join(s["id"]).split())
        yield sid, " ".join("".join(s["heading"]).split()), _lines("".join(s["text"]))

def sections():
    k, toc = fetch(BASE + "/law/iowaCode")
    titles = []
    for t in re.findall(r'href="(/law/iowaCode/chapters\?title=[^"&]+&(?:amp;)?year=\d+)"', toc):
        t = t.replace("&amp;", "&")
        if t not in titles:
            titles.append(t)
    log("titles %d" % len(titles))
    seen = set()
    for t in titles:
        year = re.search(r"year=(\d+)", t).group(1)
        k, page = fetch(BASE + t)
        chs = []
        for c in re.findall(r'sections\?codeChapter=([^"&]+)&(?:amp;)?year=', page):
            if c not in chs:
                chs.append(c)
        log("%s: %d chapters" % (t, len(chs)))
        for ch in chs:
            url = "%s/docs/code/%s/%s.html" % (BASE, year, ch)
            try:
                k, html = fetch(url)
            except Exception as e:
                log("chapter %s failed: %s" % (ch, e)); continue
            if isinstance(html, bytes):
                html = html.decode("utf-8", "ignore")
            n = 0
            for sid, head, text in chapter_sections(html):
                if not re.match(r"^\d+[A-Z]*\.\d+[A-Z]*$", sid) or sid in seen or not text or text == "Reserved.":
                    if sid not in seen and text != "Reserved.": log("ch %s odd id %r" % (ch, sid[:40]))
                    continue
                seen.add(sid); n += 1
                yield {"id": sid, "heading": head, "text": text, "url": url}
            if not n:
                log("chapter %s: no sections" % ch)
